mapper.sql:

WHERE p.is_deleted = 0 

	AND LOWER(p.name) LIKE CONCAT('%', LOWER(#{name}), '%')


	AND p.category_id = #{categoryId}


	AND p.selling_price >= #{minPrice}


	AND p.selling_price <= #{maxPrice}


	AND p.average_rating >= #{minRating}


	AND p.average_rating <= #{maxRating}


	AND p.created_at >= #{createdFrom}


	AND p.created_at <= #{createdTo}

mapper.update:
UPDATE products
SET quantity = quantity - #{quantity}
WHERE id = #{productId} 
  AND is_deleted = 0 
  AND quantity >= #{quantity}

UPDATE products SET total_ratings = total_ratings + CASE id
WHEN #{stat.productId} THEN #{stat.countIncrement}
END, rating_sum = rating_sum + CASE id
WHEN #{stat.productId} THEN #{stat.sumIncrement}
END, average_rating = ROUND(rating_sum/total_ratings, 2) WHERE id IN
#{stat.productId}
